def svg(nom, couleur="#FFFFFF", epaisseur=1.9):
    """Le document SVG complet de l'icône `nom` (KeyError si elle n'existe pas)."""
    return (f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="{couleur}" '
            f'stroke-width="{epaisseur}" stroke-linecap="round" stroke-linejoin="round">{ICONES[nom]}</svg>')
